    let currentZone = 2; // Default JB
    let countdownInterval;
    
    // 🎯 Initialize
    document.addEventListener('DOMContentLoaded', function() {
        initZoneSelector();
        renderTable();
        startCountdown();
    });
    
    // 🗺️ Zone Selector
    function initZoneSelector() {
        const buttons = document.querySelectorAll('.ilmx-johor-zone-btn');
        buttons.forEach(btn => {
            btn.addEventListener('click', function() {
                buttons.forEach(b => b.classList.remove('active'));
                this.classList.add('active');
                currentZone = parseInt(this.dataset.zone);
                document.getElementById('ilmxJohorZoneInfo').innerHTML = zoneDescriptions[currentZone];
                renderTable();
                startCountdown();
            });
        });
    }
    
    // 📊 Render Table
    function renderTable() {
        const tbody = document.getElementById('ilmxJohorTableBody');
        const data = ramadanJohor['zone' + currentZone];
        const today = new Date();
        
        let html = '';
        data.forEach((row, index) => {
            const rowDate = new Date(2026, 1, 19 + index);
            const isToday = rowDate.toDateString() === today.toDateString();
            
            html += `<tr${isToday ? ' class="today"' : ''}>
                <td>${row.day}</td>
                <td>${row.ramadan} Ramadan</td>
                <td>${row.date} 2026</td>
                <td class="time-col">${row.imsak}</td>
                <td class="time-col">${row.berbuka}</td>
            </tr>`;
        });
        
        tbody.innerHTML = html;
    }
    
    // ⏰ Countdown
    function startCountdown() {
        if (countdownInterval) clearInterval(countdownInterval);
        
        const today = new Date();
        const ramadanStart = new Date(2026, 1, 19);
        const daysDiff = Math.floor((today - ramadanStart) / (1000 * 60 * 60 * 24));
        
        if (daysDiff < 0 || daysDiff >= 30) {
            document.getElementById('ilmxJohorToday').innerHTML = 
                '<strong>Ramadan 2026 dijangka bermula 19 Feb 2026 • Cuti Umum Johor!</strong>';
            return;
        }
        
        const todayData = ramadanJohor['zone' + currentZone][daysDiff];
        const berbukaTime = todayData.berbuka.split(':');
        const targetTime = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 
            parseInt(berbukaTime[0]), parseInt(berbukaTime[1]), 0);
        
        document.getElementById('ilmxJohorToday').innerHTML = 
            `<strong>Hari ini (${todayData.ramadan} Ramadan):</strong> Imsak ${todayData.imsak} | Berbuka ${todayData.berbuka}`;
        
        countdownInterval = setInterval(function() {
            const now = new Date();
            const diff = targetTime - now;
            
            if (diff < 0) {
                document.getElementById('ilmxJohorHours').textContent = '00';
                document.getElementById('ilmxJohorMinutes').textContent = '00';
                document.getElementById('ilmxJohorSeconds').textContent = '00';
                clearInterval(countdownInterval);
                return;
            }
            
            const hours = Math.floor(diff / (1000 * 60 * 60));
            const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((diff % (1000 * 60)) / 1000);
            
            document.getElementById('ilmxJohorHours').textContent = hours.toString().padStart(2, '0');
            document.getElementById('ilmxJohorMinutes').textContent = minutes.toString().padStart(2, '0');
            document.getElementById('ilmxJohorSeconds').textContent = seconds.toString().padStart(2, '0');
        }, 1000);
    }
    
